/**
 * Segmented tab bar for in-page sections. Arrow keys move between tabs
 * (roving tabindex), matching the WAI-ARIA tabs pattern.
 */
export function SegmentedTabs<T extends string>({
  value,
  onChange,
  tabs,
  label,
  className,
}: {
  value: T;
  onChange: (v: T) => void;
  tabs: { value: T; label: ReactNode; count?: number }[];
  label: string;
  className?: string;
}) {
  const focusAt = (index: number) => {
    const next = tabs[index];
    onChange(next.value);
    requestAnimationFrame(() =>
      document.getElementById(`seg-${label}-${next.value}`)?.focus(),
    );
  };
  return (
    <div
      role="tablist"
      aria-label={label}
      className={cn(
        "inline-flex max-w-full gap-0.5 overflow-x-auto rounded-lg border border-border/60 bg-card/40 p-0.5",
        className,
      )}
      onKeyDown={(e) => {
        const i = tabs.findIndex((t) => t.value === value);
        const n = tabs.length;
        const target =
          e.key === "ArrowRight" ? (i + 1) % n
          : e.key === "ArrowLeft" ? (i - 1 + n) % n
          : e.key === "Home" ? 0
          : e.key === "End" ? n - 1
          : -1;
        if (target >= 0) {
          e.preventDefault();
          focusAt(target);
        }
      }}
    >
      {tabs.map((t) => {
        const active = t.value === value;
        return (
          <button
            key={t.value}
            id={`seg-${label}-${t.value}`}
            role="tab"
            type="button"
            aria-selected={active}
            tabIndex={active ? 0 : -1}
            onClick={() => onChange(t.value)}
            className={cn(
              "flex shrink-0 items-center gap-1.5 rounded-md px-3 py-1.5 text-xs transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
              active
                ? "bg-background text-foreground shadow-sm"
                : "text-muted-foreground hover:text-foreground",
            )}
          >
            {t.label}
            {t.count !== undefined && (
              <span className="tabular-nums text-[10px] text-muted-foreground">{t.count}</span>
            )}
          </button>
        );
      })}
    </div>
  );
}

